    "Guardado no servidor, enviado somente a este conector e nunca mais exibido. Servidores que exigem login OAuth ainda não podem ser adicionados na web.",
  "The name of a variable set where Claudex starts, not the token itself. Servers that sign in with OAuth don’t need one: use Connect after adding.":
    "O nome de uma variável definida onde o Claudex inicia, não o token em si. Servidores que fazem login com OAuth não precisam dela: use Conectar depois de adicionar.",
