  "Claudex will use your mouse and keyboard in {apps}.":
    "O Claudex usará seu mouse e teclado em {apps}.",
  "the apps you allowed": "os aplicativos que você permitiu",
  "Other apps will be hidden until it finishes.":
    "Os outros aplicativos ficarão ocultos até a conclusão.",
  "Press Esc to stop at any time.":
    "Pressione Esc para parar a qualquer momento.",
  "Let Claudex see and act in the apps you allow, working in the background or with full control of your screen. Screenshots of those apps are sent to the model.":
    "Permita que o Claudex veja e atue nos aplicativos que você autorizar, trabalhando em segundo plano ou com controle total da tela. Capturas de tela desses aplicativos são enviadas ao modelo.",
  "Background: Claudex works inside the apps you allow while you keep using your computer, and asks your permission before taking full control of your screen. Full control: Claudex takes control of your screen, mouse, and keyboard by default whenever Claudex uses an app you allow, without asking again.":
    "Segundo plano: o Claudex trabalha nos aplicativos que você autorizar enquanto você continua usando o computador e pede permissão antes de assumir o controle total da tela. Controle total: sempre que usa um aplicativo autorizado, o Claudex assume por padrão o controle da tela, do mouse e do teclado, sem perguntar novamente.",
  "Claudex uses your computer's OpenSSH. Passwords are never saved; use an SSH key and ssh-agent to connect without prompts.":
    "O Claudex usa o OpenSSH do seu computador. Senhas nunca são salvas; use uma chave SSH e o ssh-agent para se conectar sem solicitações interativas.",
  "Run Code sessions on another computer over SSH. Claudex uses this computer's OpenSSH and your SSH keys; passwords are never saved.":
    "Execute sessões do Code em outro computador via SSH. O Claudex usa o OpenSSH deste computador e suas chaves SSH; senhas nunca são salvas.",
  ".md file must contain skill name and description formatted in YAML":
    "O arquivo .md deve conter o nome e a descrição da habilidade em formato YAML",
  ".zip or .skill file must include a SKILL.md file":
    "O arquivo .zip ou .skill deve incluir um arquivo SKILL.md",
  "Claudex references the same knowledge every time you talk to it in this project.":
    "O Claudex consulta o mesmo conhecimento sempre que você conversa com ele neste projeto.",
  "Provide Claudex with relevant instructions and information for chats within {name}. This will work alongside your personal instructions and the selected style in a chat.":
    "Forneça ao Claudex instruções e informações relevantes para conversas em {name}. Elas serão usadas junto com suas instruções pessoais e o estilo selecionado na conversa.",
  "{n} installs": "{n} instalações",
  "Shared {date}": "Compartilhado em {date}",
