    "Exibindo apenas {kind} que correspondem a “{query}”.",
  "This deletes {email} from this computer together with its conversations, projects, artifacts and settings. It can't be undone.":
    "Isso exclui {email} deste computador junto com suas conversas, projetos, artefatos e configurações. Esta ação não pode ser desfeita.",
  "Scan with {method} to pay {amount}":
    "Escaneie com {method} para pagar {amount}",
  "Pay {amount} there. Your plan and balance update when the payment goes through.":
    "Pague {amount} nessa página. Seu plano e saldo serão atualizados quando o pagamento for confirmado.",
  "The payment page for {amount} opened in your browser. This window updates when the payment goes through.":
    "A página de pagamento de {amount} foi aberta no navegador. Esta janela será atualizada quando o pagamento for confirmado.",
  "Amount ({currency})": "Valor ({currency})",
  "Fee ({percent}%)": "Taxa ({percent}%)",
  "QR code to pay {amount} with {method}":
    "Código QR para pagar {amount} com {method}",
