  "{count} hooks that run commands": "{count} hooks que executam comandos",
  "Added. It also uses {services}, which need signing in before Claudex can use them.":
    "Adicionado. Ele também usa {services}, que exigem login antes que o Claudex possa usá-los.",
  "Make sure you trust a plugin before installing, updating, or using it. Plugins installed from marketplaces are not controlled by Anthropic, and Anthropic cannot verify that they will work as intended or that they won't change. See each plugin's homepage for more information.":
    "Confirme que você confia em um plugin antes de instalá-lo, atualizá-lo ou usá-lo. Plugins instalados de marketplaces não são controlados pela Anthropic, e a Anthropic não pode verificar se funcionarão como esperado ou se permanecerão inalterados. Consulte a página inicial de cada plugin para saber mais.",
  "Updated tasks · {done} of {total} done":
    "Tarefas atualizadas · {done} de {total} concluídas",
  "Bypass all permission checks and let Claudex work uninterrupted in folders you confirm. This works well for workflows like fixing lint errors or generating boilerplate code. Letting Claudex run arbitrary commands is risky and can result in data loss, system corruption, or data exfiltration (e.g., via prompt injection attacks).":
    "Ignore todas as verificações de permissão e deixe o Claudex trabalhar sem interrupções nas pastas que você confirmar. Isso é útil para tarefas como corrigir erros de lint ou gerar código padronizado. Permitir que o Claudex execute comandos arbitrários é arriscado e pode causar perda de dados, corrupção do sistema ou vazamento de dados, por exemplo, por ataques de injeção de prompt.",
  "How Claudex structures its responses in Code sessions. Applies to new sessions; the session menu can override it for a single session.":
    "Como o Claudex estrutura as respostas nas sessões do Code. Aplica-se a novas sessões; o menu da sessão pode substituir essa opção em uma sessão específica.",
