  "Afternoon, {name}": "Boa tarde por aí, {name}",
  "Career chat": "Bate-papo sobre carreira",
  "Prepare for an interview": "Me preparar para uma entrevista",
  "Help me prepare for a job interview. I'll share the role and my background, then you ask me likely questions one at a time and give feedback on each answer.":
    "Me ajude a me preparar para uma entrevista de emprego. Vou contar a vaga e minha trajetória, e você me faz as perguntas mais prováveis uma de cada vez e comenta cada resposta.",
  "Sharpen my resume": "Aprimorar meu currículo",
  "Read my resume, point out what's unclear or missing, then rewrite the weakest parts so my results stand out. Here it is:\n\n":
    "Leia meu currículo, aponte o que está confuso ou faltando e reescreva as partes mais fracas para que meus resultados se destaquem. Aqui está:\n\n",
  "Rehearse a hard conversation": "Ensaiar uma conversa difícil",
  "Role-play a conversation I need to have at work. I'll tell you who it's with and what I want to say; you play them realistically, then tell me what worked.":
    "Faça um role-play de uma conversa que preciso ter no trabalho. Vou dizer com quem é e o que quero falar; você interpreta a pessoa de forma realista e depois me diz o que funcionou.",
  "Map my next career step": "Traçar meu próximo passo na carreira",
  "Help me plan my next career step. Ask me what I do now, what I enjoy and where I'd like to be, then suggest a few paths and what each would take.":
    "Me ajude a planejar meu próximo passo na carreira. Pergunte o que faço hoje, do que gosto e aonde quero chegar, e depois sugira alguns caminhos e o que cada um exigiria.",
  "Handle a tricky work situation":
    "Lidar com uma situação delicada no trabalho",
  "Help me handle a tricky situation at work: lay out my options and help me pick a next step. Here's what's going on: ":
    "Me ajude a lidar com uma situação delicada no trabalho: apresente minhas opções e me ajude a escolher o próximo passo. Veja o que está acontecendo: ",
