  "Automatically archive desktop sessions when the associated pull request is merged or closed. Archiving also removes the session’s worktree and deletes its branch once the pull request is merged. Work that isn’t pushed is kept.":
    "Arquivar automaticamente as sessões da área de trabalho quando a pull request associada for mesclada ou fechada. Depois da mesclagem, arquivar também remove o worktree da sessão e exclui o branch. O trabalho não enviado é mantido.",
  "Archive this session when its pull request is merged or closed. Archiving also removes the session’s worktree and deletes its branch once the pull request is merged. Work that isn’t pushed is kept. This session only; other sessions follow the default in Settings → Claudex Code.":
    "Arquivar esta sessão quando a pull request dela for mesclada ou fechada. Depois da mesclagem, arquivar também remove o worktree da sessão e exclui o branch. O trabalho não enviado é mantido. Somente esta sessão; as outras seguem o padrão em Configurações → Claudex Code.",
  "Git won’t check out a branch in two folders at once. Run git worktree list in the repository to see which folder has this branch, switch that folder to a different branch, then try again.":
    "O Git não permite fazer checkout de um branch em duas pastas ao mesmo tempo. Execute git worktree list no repositório para ver qual pasta está com esse branch, mude essa pasta para outro branch e tente novamente.",
