  "Turn this idea into a diagram, chart, or visual: ":
    "Transforme esta ideia em um diagrama, gráfico ou visual: ",
  "Get this as a document you can edit and share.":
    "Tenha isto como um documento que você pode editar e compartilhar.",
  "Create a document": "Criar um documento",
  "Turn your last answer into a document I can edit and share. Build it right here in this chat and ask me at most one question. If something’s missing, use a sensible default and tell me what you assumed.":
    "Transforme sua última resposta em um documento que eu possa editar e compartilhar. Crie-o aqui mesmo nesta conversa e me faça no máximo uma pergunta. Se algo estiver faltando, use um padrão razoável e me diga o que você presumiu.",
  "Write a document to go with what you just made, and refer to that work by name so the two stay linked. Build it right here in this chat and ask me at most one question. If something’s missing, use a sensible default and tell me what you assumed.":
    "Escreva um documento que acompanhe o que você acabou de criar e cite esse trabalho pelo nome, para que os dois fiquem vinculados. Crie o documento aqui mesmo nesta conversa e me faça no máximo uma pergunta. Se faltar alguma informação, use um padrão sensato e me diga o que você presumiu.",
  "Get this as a spreadsheet you can sort and update.":
    "Receba isso como uma planilha que você pode ordenar e atualizar.",
  "Create a spreadsheet": "Criar uma planilha",
  "Put the numbers and details from your last answer into a spreadsheet I can sort and update. Build it right here in this chat and ask me at most one question. If something’s missing, use a sensible default and tell me what you assumed.":
    "Coloque os números e detalhes da sua última resposta em uma planilha que eu possa ordenar e atualizar. Crie a planilha aqui mesmo nesta conversa e me faça no máximo uma pergunta. Se faltar alguma coisa, use um padrão sensato e me diga o que você assumiu.",
  "Make a spreadsheet to go with what you just made, and refer to that work by name so the two stay linked. Build it right here in this chat and ask me at most one question. If something’s missing, use a sensible default and tell me what you assumed.":
    "Crie uma planilha para acompanhar o que você acabou de fazer e se refira a esse trabalho pelo nome, para que os dois fiquem vinculados. Crie a planilha aqui mesmo nesta conversa e me faça no máximo uma pergunta. Se algo estiver faltando, use um padrão sensato e me diga o que você presumiu.",
  "Get this as a slide deck you can present.":
    "Transforme isso em uma apresentação de slides pronta para apresentar.",
  "Create a slide deck": "Criar uma apresentação de slides",
  "Turn your last answer into a slide deck I can present. Build it right here in this chat and ask me at most one question. If something’s missing, use a sensible default and tell me what you assumed.":
    "Transforme sua última resposta em uma apresentação de slides que eu possa apresentar. Crie tudo aqui mesmo nesta conversa e me faça no máximo uma pergunta. Se faltar alguma coisa, use um padrão razoável e me diga o que você presumiu.",
  "Make a slide deck from what you just made, and refer to that work by name so the two stay linked. Build it right here in this chat and ask me at most one question. If something’s missing, use a sensible default and tell me what you assumed.":
    "Crie uma apresentação de slides a partir do que você acabou de fazer e cite esse trabalho pelo nome, para que os dois fiquem vinculados. Monte a apresentação aqui mesmo nesta conversa e me faça no máximo uma pergunta. Se algo estiver faltando, use um padrão sensato e me diga o que você presumiu.",
  "Get this as a one-page brief for your team.":
    "Receba isto como um resumo de uma página para sua equipe.",
  "Write a brief": "Escrever um resumo executivo",
  "Turn your last answer into a one-page brief for my team. Build it right here in this chat and ask me at most one question. If something’s missing, use a sensible default and tell me what you assumed.":
    "Transforme sua última resposta em um briefing de uma página para minha equipe. Crie o briefing aqui mesmo nesta conversa e me faça no máximo uma pergunta. Se faltar alguma informação, use um padrão sensato e me diga o que você presumiu.",
  "Write a one-page brief that summarizes what you just made, and refer to that work by name so the two stay linked. Build it right here in this chat and ask me at most one question. If something’s missing, use a sensible default and tell me what you assumed.":
    "Escreva um briefing de uma página que resuma o que você acabou de criar e cite esse trabalho pelo nome, para que os dois fiquem vinculados. Crie o briefing aqui mesmo nesta conversa e me faça no máximo uma pergunta. Se faltar alguma coisa, use um padrão sensato e me diga o que você presumiu.",
  "Get this as an email draft, ready to send.":
    "Receba isto como um rascunho de e-mail, pronto para enviar.",
  "Draft an email": "Escrever um rascunho de e-mail",
  "Turn your last answer into an email draft I can send. Build it right here in this chat and ask me at most one question. If something’s missing, use a sensible default and tell me what you assumed.":
    "Transforme sua última resposta em um rascunho de e-mail que eu possa enviar. Crie o rascunho aqui mesmo nesta conversa e me faça no máximo uma pergunta. Se faltar alguma informação, use um padrão razoável e me diga o que você presumiu.",
  "Draft an email that shares what you just made, and refer to that work by name so the two stay linked. Build it right here in this chat and ask me at most one question. If something’s missing, use a sensible default and tell me what you assumed.":
    "Escreva um rascunho de e-mail que compartilhe o que você acabou de criar e cite esse trabalho pelo nome, para que os dois fiquem vinculados. Monte tudo aqui mesmo nesta conversa e me faça no máximo uma pergunta. Se faltar alguma informação, use um padrão razoável e me diga o que você presumiu.",
  "Get this as a task list you can work through.":
    "Receba isto como uma lista de tarefas para você concluir.",
  "Make a task list": "Criar uma lista de tarefas",
  "Turn your last answer into a task list with clear next steps. Build it right here in this chat and ask me at most one question. If something’s missing, use a sensible default and tell me what you assumed.":
    "Transforme sua última resposta em uma lista de tarefas com próximos passos claros. Monte a lista aqui mesmo nesta conversa e me faça no máximo uma pergunta. Se algo estiver faltando, use um padrão sensato e me diga o que você presumiu.",
  "Make a task list of next actions from what you just made, and refer to that work by name so the two stay linked. Build it right here in this chat and ask me at most one question. If something’s missing, use a sensible default and tell me what you assumed.":
    "Faça uma lista de tarefas com as próximas ações a partir do que você acabou de criar e se refira a esse trabalho pelo nome, para que os dois fiquem vinculados. Monte a lista aqui mesmo nesta conversa e me faça no máximo uma pergunta. Se algo estiver faltando, use um padrão sensato e me diga o que você presumiu.",
  "Make this an artifact I can keep editing and share.":
    "Transforme isto em um artifact que eu possa continuar editando e compartilhar.",
  "Turn this into a file I can download and send as is.":
    "Transforme isso em um arquivo que eu possa baixar e enviar como está.",
