  "Permission mode is set to Auto.":
    "O modo de permissão está definido como Automático.",
  "Skip all approvals is on.": "Ignorar todas as aprovações está ativado.",
  "Claudex runs on its own and pauses if anything looks unsafe. This includes using your connectors and apps on your computer, unless you turn them off.":
    "O Claudex trabalha por conta própria e pausa se algo parecer inseguro. Isso inclui usar seus conectores e aplicativos no computador, a menos que você os desative.",
  "Claudex never pauses, even for unsafe actions. This includes using your connectors and apps on your computer. You can turn off individual connectors in the + menu.":
    "O Claudex nunca pausa, mesmo em ações inseguras. Isso inclui usar seus conectores e aplicativos no computador. Você pode desativar conectores individuais no menu +.",
  "Claudex will work, browse the web, and use any connectors you’ve enabled without pausing for approval. This can put your data at risk.":
    "O Claudex trabalhará, navegará na web e usará os conectores ativados sem pausar para pedir aprovação. Isso pode colocar seus dados em risco.",
  "See safe use tips": "Ver dicas de uso seguro",
