  "Pattern must end with $ so it can't match a longer host":
    "O padrão deve terminar com $ para não corresponder a um host mais longo",
  "Pattern must start with ^https://": "O padrão deve começar com ^https://",
  "Remove the @ — userinfo before the host isn't allowed":
    "Remova @ — informações do usuário antes do host não são permitidas",
  "Server URL must start with https://":
    "A URL do servidor deve começar com https://",
  "The subdomain slot can't use wildcards that match `/`, `.`, `?`, `#` or `@` — use a character class like [a-z0-9-]+ instead of .+ or \\S+":
    "O subdomínio não pode usar curingas que correspondam a `/`, `.`, `?`, `#` ou `@` — use uma classe como [a-z0-9-]+ em vez de .+ ou \\S+",
  "This field is required": "Este campo é obrigatório",
