  "Read safe use tips": "Ler dicas de uso seguro",
  "Computer use is on. To finish setup, grant the macOS permissions below.":
    "O uso do computador está ativado. Para concluir, conceda as permissões do macOS abaixo.",
  Denied: "Negado",
  "Not requested": "Não solicitado",
  "Background computer use": "Uso do computador em segundo plano",
  "Claudex will see your whole screen and use your mouse and keyboard on it. You’ll approve the apps Claudex asks for, but on this system access can’t be limited to them, and you won’t confirm each step Claudex performs.":
    "O Claudex verá sua tela inteira e usará o mouse e o teclado. Você aprovará os apps solicitados, mas neste sistema o acesso não pode ser limitado a eles, e você não confirmará cada etapa.",
  "Claudex will see the apps you approve and click and type in them, working in the background while you keep using your computer or taking full control of your screen. Which of those Claudex does by default is set under Settings → This computer → Computer use. You’ll approve each app, but not confirm each step Claudex performs.":
    "O Claudex verá os apps que você aprovar e clicará e digitará neles, em segundo plano enquanto você usa o computador ou com controle total da tela. O padrão é definido em Configurações → Este computador → Uso do computador. Você aprovará cada app, mas não confirmará cada etapa.",
  "Claudex can now control your applications in the background without taking over your screen, and will ask your permission if Claudex needs full control of your mouse and keyboard. If you’d prefer Claudex to default to full control instead of background mode, you can change this at any time under Settings → This computer → Computer use.":
    "Agora o Claudex pode controlar seus apps em segundo plano sem assumir a tela, e pedirá permissão se precisar do controle total do mouse e do teclado. Se preferir o controle total como padrão, você pode mudar isso a qualquer momento em Configurações → Este computador → Uso do computador.",
