  "This app's file ownership is preventing auto-updates from working smoothly. Claudex needs to fix the ownership, which requires administrator access. You'll be prompted for your fingerprint or password.":
    "A propriedade dos arquivos deste aplicativo está impedindo o funcionamento correto das atualizações automáticas. O Claudex precisa corrigir a propriedade, o que requer acesso de administrador. Sua impressão digital ou senha será solicitada.",
  "Fix ownership": "Corrigir propriedade",
