  "Make sure you trust a plugin before installing, updating, or using it. Plugins installed from marketplaces are not controlled by Claudex, and Claudex cannot verify that they will work as intended or that they won't change. See each plugin's homepage for more information.":
    "Confirme que você confia em um plugin antes de instalá-lo, atualizá-lo ou usá-lo. Plugins instalados de marketplaces não são controlados pela Claudex, e a Claudex não pode verificar se funcionarão como esperado ou se permanecerão inalterados. Consulte a página inicial de cada plugin para saber mais.",
