  "Search by name": "Pesquisar por nome",
  "Build connectors and plugins": "Criar conectores e plugins",
  "A connector is an MCP server: it speaks the Model Context Protocol over streamable HTTP, signs people in with OAuth or a token, and describes each tool’s inputs and effects plainly. A plugin bundles skills, connectors and instructions into one package. Add your connector as a custom connector under Customize → Connectors and try it in a chat before you send it with Submit to the directory.":
    "Um conector é um servidor MCP: ele fala o Model Context Protocol via HTTP com streaming, faz o login com OAuth ou um token e descreve com clareza as entradas e os efeitos de cada ferramenta. Um plugin reúne skills, conectores e instruções em um único pacote. Adicione seu conector como conector personalizado em Personalizar → Conectores e teste em uma conversa antes de enviá-lo com Enviar ao diretório.",
